use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
    out: Vec<string>,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k { return true }
            if x < k { cur = self.lefts[cur as usize] } else { cur = self.rights[cur as usize] }
        }
        false
    }

    fn new_node(self, x: int) -> int {
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        (self.keys.len() as int) - 1
    }

    fn insert_at(self, node: int, x: int) -> int {
        if node < 0 { return self.new_node(x) }
        let k = self.keys[node as usize]
        if x < k {
            let l = self.lefts[node as usize]
            let r = self.insert_at(l, x)
            self.lefts[node as usize] = r
        } else {
            let l = self.rights[node as usize]
            let r = self.insert_at(l, x)
            self.rights[node as usize] = r
        }
        node
    }

    fn min_key(self, node: int) -> int {
        let mut cur = node
        while self.lefts[cur as usize] >= 0 {
            cur = self.lefts[cur as usize]
        }
        self.keys[cur as usize]
    }

    fn delete_at(self, node: int, x: int) -> int {
        if node < 0 { return node }
        let k = self.keys[node as usize]
        if x < k {
            let l = self.lefts[node as usize]
            let r = self.delete_at(l, x)
            self.lefts[node as usize] = r
            return node
        }
        if x > k {
            let l = self.rights[node as usize]
            let r = self.delete_at(l, x)
            self.rights[node as usize] = r
            return node
        }
        let l = self.lefts[node as usize]
        let r = self.rights[node as usize]
        if l < 0 { return r }
        if r < 0 { return l }
        let s = self.min_key(r)
        self.keys[node as usize] = s
        let nr = self.delete_at(r, s)
        self.rights[node as usize] = nr
        node
    }

    fn height_at(self, node: int) -> int {
        if node < 0 { return 0 }
        let a = self.height_at(self.lefts[node as usize])
        let b = self.height_at(self.rights[node as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, node: int) {
        if node < 0 { return }
        self.walk(self.lefts[node as usize])
        self.out.push("${self.keys[node as usize]}")
        self.walk(self.rights[node as usize])
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1, out: [] }
    for line in text.lines() {
        let parts = line.split_whitespace().map(|s| s.to_string()).collect::<Vec<string>>()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) {
                println("dup")
            } else {
                let r = t.insert_at(t.root, x)
                t.root = r
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            if t.contains(x) {
                let r = t.delete_at(t.root, x)
                t.root = r
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            t.out = []
            t.walk(t.root)
            if t.out.len() == 0 { println("<empty>") } else { println(t.out.join(" ")) }
        } else if cmd == "height" {
            println("${t.height_at(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else { println("${t.min_key(t.root)}") }
        } else if cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut cur = t.root
                while t.rights[cur as usize] >= 0 { cur = t.rights[cur as usize] }
                println("${t.keys[cur as usize]}")
            }
        }
    }
}

